import React from 'react';
import './Navbar.css';

const Navbar = () => {
  return (
    <nav className="floating-navbar">
      <span className="navbar-brand"></span>
      <div className="navbar-links">
        <a href="">Save</a>
      </div>
    </nav>
  );
};

export default Navbar;
